!function(t){function r(r){for(var n,a,m=r[0],o=r[1],u=r[2],g=0,k=[];g<m.length;g++)a=m[g],Object.prototype.hasOwnProperty.call(i,a)&&i[a]&&k.push(i[a][0]),i[a]=0;for(n in o)Object.prototype.hasOwnProperty.call(o,n)&&(t[n]=o[n]);for(c&&c(r);k.length;)k.shift()();return p.push.apply(p,u||[]),e()}function e(){for(var t,r=0;r<p.length;r++){for(var e,a=p[r],m=!0,o=1;o<a.length;o++)e=a[o],0!==i[e]&&(m=!1);m&&(p.splice(r--,1),t=n(n.s=a[0]))}return t}function n(r){if(a[r])return a[r].exports;var e=a[r]={i:r,l:!1,exports:{}};return t[r].call(e.exports,e,e.exports,n),e.l=!0,e.exports}var a={},i={15:0},p=[];n.m=t,n.c=a,n.d=function(t,r,e){n.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:e})},n.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},n.t=function(t,r){if(1&r&&(t=n(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var e=Object.create(null);if(n.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var a in t)n.d(e,a,function(r){return t[r]}.bind(null,a));return e},n.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return n.d(r,"a",r),r},n.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},n.p="";var m=window.webpackJsonp=window.webpackJsonp||[],o=m.push.bind(m);m.push=r,m=m.slice();for(var u=0;u<m.length;u++)r(m[u]);var c=o;p.push([19,0]),e()}({19:function(t,r,e){"use strict";e.r(r);var n=e(0);Object(n.a)("uk","army",e(20),e(1))},20:function(t){t.exports=JSON.parse('{"category":[{"name":"英国","link":"uk_shortcut"},{"name":"陆战武器","link":"uk_army"},{"name":"坦克","link":"uk_army#uk_army_tank"}],"model":"“瓦伦丁”步兵坦克","description":"<h6>综述：</h6><p>瓦伦丁步兵坦克是英国维克斯公司在1938年开始研制，1940年正式服役的一种中轻型坦克，由于其交付日子正是情人节，因此也有将此坦克用“情人节”来命名。这是英国在二战期间产量最多的一种坦克，至1944年止，一共生产了8275辆（其中有1420辆为加拿大生产）。该款坦克有Ⅰ、Ⅱ、Ⅲ、Ⅳ、Ⅴ…等共11种型号，该坦克除装备英军外，还有约2400辆（含加拿大生产的1000多辆）按租借法案等条令给了苏联军队，也有部分装备了新西兰等同盟国部队。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}瓦伦丁Ⅰ型步兵坦克{{image}}imgs/uk/army/uk_army_tankvt_11.jpg{{text}}瓦伦丁Ⅱ型步兵坦克<br>隶属英军第1坦克旅的一辆瓦伦丁Ⅱ型步兵坦克。该坦克在1941年底“十字军”战役中被德军88炮摧毁。{{image}}imgs/uk/army/uk_army_tankvt_12.jpg{{text}}瓦伦丁Ⅲ型步兵坦克<br>1942年7月，隶属苏军沃罗涅什方面军第5坦克集团军第7装甲军的一辆瓦伦丁Ⅲ型步兵坦克。{{image}}imgs/uk/army/uk_army_tankvt_13.jpg{{text}}瓦伦丁IX型步兵坦克<br>1944年，在波兰战场，一辆隶属苏联白俄罗斯第1方面军第2坦克军第5独立摩托化团的瓦伦丁IX型步兵坦克，坦克已改装57mm（6磅）火炮，炮塔与早期型号已有区别。{{image}}imgs/uk/army/uk_army_tankvt_14.jpg{{text}}瓦伦丁XI型步兵坦克<br>这辆坦克是瓦伦丁步兵坦克的最后一个型号，1943年将原来的6磅火炮更换为75mm反坦克炮，炮塔也换上了新的护盾。{{image}}imgs/uk/army/uk_army_tankvt_15.jpg","description":"<h6>瓦伦丁步兵坦克</h6><p>该型坦克是英国在二战初期所研制，它发动机功率不大，装甲也不及同期生产的马蒂尔达，且乘员舒适度也较差，但它的底盘较大，可安装各种武器，同时坦克的动力装置可靠性较高。</p><p>瓦伦丁步兵坦克先后进行多种型号的改进，发动机从最初型号用的汽油机到后来型号改用柴油机，武器从早期的2磅火炮到中期的6磅火炮，到后期更装上了75mm口径火炮。</p><p>坦克参数：</p><p>车长：5.41m，车宽：2.63m, 车高：2.27m，车重：17.7t，乘员：3人；</p><p>最高车速：24km/h，最大行程：145km；</p><p>装甲厚度：8-65mm；武器装备：Ⅰ-VII型2磅（40mm）火炮，VIII-X型6磅（57mm）火炮，最后的XI型75mm反坦克炮；辅助武器：一挺7.92mm口径机枪。</p>","caption":""}],"part2title":"战场上的瓦伦丁步兵坦克","part2description":"<p>瓦伦丁步兵坦克第一次实战是在北非战场，在和德、意军的对抗中表现出色。英军第8军装备的瓦伦丁步兵坦克曾在阿拉曼地区持续了3000英里的推进，1942年11月，英军共有115辆瓦伦丁步兵坦克参加了第2次阿拉曼战役的“增压”行动，英军第9装甲旅的2个瓦伦丁步兵坦克团配合步兵一起向德军阵地发动猛烈攻击，摧毁了35门德、意军的反坦克炮，帮助第2装甲旅打退了德军第15装甲师的反攻，尽管损失惨重（全旅坦克损失75%），仍完满地完成了战斗任务。此外，英军还曾率领15辆瓦伦丁步兵坦克在马达加斯加作战，1942年还有部分瓦伦丁步兵坦克装备新西兰军队在太平洋与日军作战。而苏军接收的2000多辆瓦伦丁步兵坦克大多都换装了76.2mm火炮，从1941年底莫斯科战役开始一直跟随苏军装甲部队作战，直到1945年二战结束。</p>","part2content":[{"image":"imgs/uk/army/uk_army_tankvt_31.jpg","description":"正在行进中的一队瓦伦丁Ⅱ型步兵坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankvt_32.jpg","description":"北非战场上英军的一辆瓦伦丁Ⅲ型步兵坦克。该坦克在炮塔上方装上了一挺机枪。","caption":""},{"image":"imgs/uk/army/uk_army_tankvt_33.jpg","description":"1942年北非战场，在利比亚港口城市托布鲁克的一辆英军瓦伦丁Ⅲ型步兵坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankvt_34.jpg","description":"1942年在北非战场，英军的瓦伦丁步兵坦克正在与德军作战。","caption":""},{"image":"imgs/uk/army/uk_army_tankvt_35.jpg","description":"1942年，北非战场，一队瓦伦丁步兵坦克正在作战斗前的集结。","caption":""},{"image":"imgs/uk/army/uk_army_tankvt_36.jpg","description":"1942年在北非战场，英军的瓦伦丁步兵坦克正在准备向德军阵地进攻。","caption":""},{"image":"imgs/uk/army/uk_army_tankvt_37.jpg","description":"1945年3月，一队在匈牙利行进的瓦伦丁IX、X型步兵坦克（隶属部队未知）。","caption":""},{"image":"imgs/uk/army/uk_army_tankvt_38.jpg","description":"众多加装了水陆两栖装置的瓦伦丁步兵坦克，应是准备登陆作战用，但实际上并未用上，在诺曼底登陆的英军部队配备的是谢尔曼坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankvt_39.jpg","description":"一辆瓦伦丁架桥坦克下在作架桥行动，这种架桥坦克很快就被效率更高的丘吉尔架桥坦克替代，只有少部分仍在缅甸服役。","caption":""}]}')}});